import{_ as e,o as n,c as a,ao as r}from"./chunks/framework.CYQiVpEK.js";const x=JSON.parse('{"title":"Capability matrix","description":"","frontmatter":{},"headers":[],"relativePath":"capability_matrix.md","filePath":"capability_matrix.md","lastUpdated":null}'),d={name:"capability_matrix.md"};function i(l,t,s,c,o,g){return n(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="Capability-matrix" tabindex="-1">Capability matrix <a class="header-anchor" href="#Capability-matrix" aria-label="Permalink to &quot;Capability matrix {#Capability-matrix}&quot;">​</a></h1><p>This page tracks VTK.jl&#39;s current feature coverage at four different layers. It is a manually maintained snapshot of the repository on <strong>2026-11-24</strong>, not a claim of PyVista feature parity.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Symbol</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">✅</td><td style="text-align:right;">Present for the currently advertised scope</td></tr><tr><td style="text-align:right;">◐</td><td style="text-align:right;">Partial, indirect, experimental, or with important caveats</td></tr><tr><td style="text-align:right;">—</td><td style="text-align:right;">Absent, or no dedicated coverage</td></tr><tr><td style="text-align:right;">N/A</td><td style="text-align:right;">Not applicable to this layer</td></tr></tbody></table><p>The columns have deliberately strict meanings:</p><ul><li><p><strong>Raw binding</strong>: the required classes/methods are registered in the current WrapIt-generated + shim <code>libvtk_julia</code>. A class merely being present in <code>VTK_jll</code> does not count.</p></li><li><p><strong>High-level API</strong>: a supported Julian convenience in <code>src/*.jl</code>. Calling a generated VTK method or using <code>_cp</code> does not count as high-level coverage.</p></li><li><p><strong>Tested</strong>: direct automated behavioral coverage in <code>test/</code>. Class registration and indirect use alone do not count; ◐ indicates smoke, indirect, or incomplete option/type coverage.</p></li><li><p><strong>Documented</strong>: a user-facing tutorial or public API documentation. A roadmap entry or an implementation-only note does not count as full user documentation.</p></li></ul><p>The matrix should be updated in the same change as the corresponding binding, Julian API, tests, or documentation. The authoritative sources are <code>gen/wrapit/VTK.wit.in</code> and the generated/shim sources for raw coverage, <code>src/*.jl</code> for high-level coverage, <code>test/*.jl</code> for tests, and <code>docs/src</code> for documentation. The follow-up plan is in <a href="https://github.com/ffrancesco94/VTK.jl/blob/main/STATUS.md#7-recommended-sequence--toward-a-julian-pyvista" target="_blank" rel="noreferrer"><code>STATUS.md</code></a>.</p><h2 id="Data-model-and-arrays" tabindex="-1">Data model and arrays <a class="header-anchor" href="#Data-model-and-arrays" aria-label="Permalink to &quot;Data model and arrays {#Data-model-and-arrays}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">Raw binding</th><th style="text-align:center;">High-level API</th><th style="text-align:center;">Tested</th><th style="text-align:center;">Documented</th><th style="text-align:right;">Current scope / next gap</th></tr></thead><tbody><tr><td style="text-align:right;">Numeric array factories and scalar-type discovery</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;"><code>vtkDataArray</code> plus concrete numeric factories; <code>data_array(T, ncomp)</code> and <code>VTKDataArray{T}</code> cover VTK&#39;s numeric scalar types.</td></tr><tr><td style="text-align:right;">VTK-memory → Julia zero-copy AOS views</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;"><code>data</code>, <code>raw_data</code>, typed indexing, and GC-retention tests. Views dangle after reallocation; growth is uninitialized.</td></tr><tr><td style="text-align:right;">Existing Julia-buffer → VTK zero-copy adoption</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Current zero-copy path is in the VTK-to-Julia direction. Define ownership before adding the reverse direction.</td></tr><tr><td style="text-align:right;">SOA/variant storage and string arrays</td><td style="text-align:center;">◐</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">◐</td><td style="text-align:right;">The abstract array API exists, but typed views are numeric host-side AOS only; concrete <code>vtkStringArray</code>/<code>vtkVariantArray</code> support is not wrapped.</td></tr><tr><td style="text-align:right;">Unstructured-grid construction from Julia data</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;"><code>UnstructuredGrid(points, cells)</code> works, but inserts point-by-point, converts through <code>Float64</code>, and needs stronger connectivity validation and a bulk path.</td></tr><tr><td style="text-align:right;">PolyData topology construction</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">◐</td><td style="text-align:center;">—</td><td style="text-align:right;">Raw factory and verts/lines/polys/strips methods exist. Tests only exercise an empty <code>PolyData_new()</code>; no Julia-data topology constructor exists.</td></tr><tr><td style="text-align:right;">ImageData construction and metadata</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Raw factory and dimensions/origin/spacing methods exist; no ergonomic constructor or structured-array interface.</td></tr><tr><td style="text-align:right;">RectilinearGrid construction</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Raw factory and x/y/z coordinate-array setters exist; no <code>RectilinearGrid(x, y, z)</code> convenience.</td></tr><tr><td style="text-align:right;">StructuredGrid construction</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Raw factory, points, and dimensions APIs exist; no coordinates-plus-dimensions constructor.</td></tr><tr><td style="text-align:right;">Cell/point iterators and VTKBase <code>MeshCell</code> conversion</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;"><code>cell(s)</code>, <code>eachcell</code>, <code>eachpoint</code>, <code>coordinates</code>, and WriteVTK-compatible connectivity. High-order/polyhedral conveniences remain limited.</td></tr><tr><td style="text-align:right;">Bounds, center, dimensions, extent, origin, spacing, ranges</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">◐</td><td style="text-align:center;">—</td><td style="text-align:right;">Many raw getters exist. Current high-level coverage is mainly <code>npoints</code>/<code>ncells</code>; structured metadata is checked indirectly through I/O.</td></tr><tr><td style="text-align:right;">Point/cell/general field data and active attributes</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:right;">High-level point/cell arrays and active scalars exist. General field data, active vectors/tensors/normals/texture coordinates, nonnumeric arrays, and dictionary-like access are missing.</td></tr><tr><td style="text-align:right;">Downcast, null handling, and shallow/deep copy</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:right;">Exact-name downcast covers six concrete types; unknown/null outputs are brittle. Deep-copy snapshots are exposed mainly through temporal readers.</td></tr><tr><td style="text-align:right;">Tabular data (<code>vtkTable</code>)</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Wrap <code>vtkTable</code>/<code>vtkTableAlgorithm</code> and necessary abstract-array support for native tabular datasets, Tables.jl integration, probe results, and charts. VTK 9.7 has no <code>vtkTableData</code> class.</td></tr></tbody></table><h2 id="Readers,-writers,-and-file-formats" tabindex="-1">Readers, writers, and file formats <a class="header-anchor" href="#Readers,-writers,-and-file-formats" aria-label="Permalink to &quot;Readers, writers, and file formats {#Readers,-writers,-and-file-formats}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">Raw binding</th><th style="text-align:center;">High-level API</th><th style="text-align:center;">Tested</th><th style="text-align:center;">Documented</th><th style="text-align:right;">Current scope / next gap</th></tr></thead><tbody><tr><td style="text-align:right;">XML unstructured grid (<code>.vtu</code>)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">Round trips, WriteVTK/ReadVTK interoperability, compressed output, and raw-appended output.</td></tr><tr><td style="text-align:right;">XML PolyData (<code>.vtp</code>)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:right;"><code>read_vtp</code>/<code>write_vtp</code> exist but lack a dedicated XML round-trip/oracle test.</td></tr><tr><td style="text-align:right;">XML image/rectilinear/structured grids (<code>.vti/.vtr/.vts</code>)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">Read and VTK round trips are tested. Independent write-side assertions are uneven, especially for <code>.vtr</code>/<code>.vts</code>.</td></tr><tr><td style="text-align:right;">XML multiblock (<code>.vtm</code>)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">Numeric flat access plus manual nested descent; named/recursive composite abstractions are missing.</td></tr><tr><td style="text-align:right;">Legacy VTK (<code>.vtk</code>)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">✅</td><td style="text-align:right;">Generic reader/writer tested with unstructured grids only; high-level output is ASCII and other dataset types need coverage.</td></tr><tr><td style="text-align:right;">EnSight Gold and CGNS readers</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">Steady and transient reads, out-of-order steps, and time lookup. Snapshot/option coverage is not identical for both formats.</td></tr><tr><td style="text-align:right;">EnSight/CGNS writers</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Reader-only at present.</td></tr><tr><td style="text-align:right;">Parallel PolyData summary (<code>.pvtp</code>)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">Serial reader merges pieces into one <code>PolyData</code>; this is not distributed execution.</td></tr><tr><td style="text-align:right;">Other parallel XML and <code>.pvd</code> collections</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Add <code>.pvtu</code>/<code>.pvti</code>/<code>.pvtr</code>/<code>.pvts</code>, parallel writers, and general time-series collections.</td></tr><tr><td style="text-align:right;">Generic extension-dispatching read/save</td><td style="text-align:center;">N/A</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Users must choose <code>read_vtu</code>, <code>read_cgns</code>, etc. Add a common frontend and extensible reader/writer registry.</td></tr><tr><td style="text-align:right;">Uniform encoding/compression/binary controls</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:right;">Raw XML and legacy controls exist. Only <code>write_vtu</code> exposes <code>raw_appended</code>; other XML writers hard-code compression and legacy writing lacks a binary keyword.</td></tr><tr><td style="text-align:right;">STL/PLY/OBJ, XDMF/VTKHDF, OpenFOAM/Exodus/Fluent/Gmsh</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Prioritize by workflow demand after the common I/O frontend exists.</td></tr></tbody></table><h2 id="Filters,-sources,-and-pipelines" tabindex="-1">Filters, sources, and pipelines <a class="header-anchor" href="#Filters,-sources,-and-pipelines" aria-label="Permalink to &quot;Filters, sources, and pipelines {#Filters,-sources,-and-pipelines}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">Raw binding</th><th style="text-align:center;">High-level API</th><th style="text-align:center;">Tested</th><th style="text-align:center;">Documented</th><th style="text-align:right;">Current scope / next gap</th></tr></thead><tbody><tr><td style="text-align:right;">Implicit plane, clip, and slice</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">Analytic unit-hex checks exist. Clip&#39;s output-type contract needs correction and input/configuration semantics need review.</td></tr><tr><td style="text-align:right;">Contour and external-surface extraction</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">Basic analytic paths work. Contour currently changes the input&#39;s active scalars; only part of the raw configuration is exposed.</td></tr><tr><td style="text-align:right;">Cell ↔ point conversion</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">✅</td><td style="text-align:right;">Constant/linear analytic checks exist; <code>arrays=</code>, pass-data, and input-type combinations need broader tests.</td></tr><tr><td style="text-align:right;">Calculator, gradient, and threshold</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">✅</td><td style="text-align:right;">Mainly point-scalar subsets are exposed. Gradient hard-codes unstructured output; raw vector/derivative options and threshold semantics need systematic coverage.</td></tr><tr><td style="text-align:right;">Static stream tracing</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">✅</td><td style="text-align:right;">A constant-vector streamline is tested. Integration controls, seed variants, and direction validation are incomplete; selecting vectors mutates input state.</td></tr><tr><td style="text-align:right;">Particle/path tracing</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">—</td><td style="text-align:center;">◐</td><td style="text-align:right;">Explicitly experimental: a static-grid execution crashed and there is no validated execution example. Keep quarantined until fixed.</td></tr><tr><td style="text-align:right;">Line source and line probing</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">✅</td><td style="text-align:right;">Line generation works. Probe tests check counts/array presence more than values; <code>sample_over_line</code>&#39;s <code>scalars</code> keyword is currently ignored.</td></tr><tr><td style="text-align:right;">Persistent/lazy pipelines, connections, and ports</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:right;">Raw input connections, output ports, time updates, progress, and cancellation exist. High-level filters eagerly execute and return only output port zero.</td></tr><tr><td style="text-align:right;">General geometry sources beyond lines</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Add sphere, box/cube, plane, cylinder, cone, arrow, point-cloud, and structured sources.</td></tr><tr><td style="text-align:right;">Transforms, connectivity, extraction, cleanup, and merging</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Add translate/rotate/scale/reflect, feature edges, connected regions, point/cell subsets, clean/merge, append, and triangulation.</td></tr><tr><td style="text-align:right;">Surface processing and analysis</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Add normals, smoothing, decimation, subdivision, shrink, extrusion, tube/glyph, cell sizes/quality, integration, and warp.</td></tr></tbody></table><h2 id="Composite-and-temporal-data" tabindex="-1">Composite and temporal data <a class="header-anchor" href="#Composite-and-temporal-data" aria-label="Permalink to &quot;Composite and temporal data {#Composite-and-temporal-data}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">Raw binding</th><th style="text-align:center;">High-level API</th><th style="text-align:center;">Tested</th><th style="text-align:center;">Documented</th><th style="text-align:right;">Current scope / next gap</th></tr></thead><tbody><tr><td style="text-align:right;">Flat multiblock construction and numeric indexing</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;"><code>MultiBlockDataSet(n)</code>, <code>nblocks</code>, <code>block</code>, and <code>set_block!</code>. Ownership wording must be reconciled with the reference-counted shim implementation.</td></tr><tr><td style="text-align:right;">Named blocks and recursive composite traversal</td><td style="text-align:center;">◐</td><td style="text-align:center;">—</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:right;">Raw metadata primitives exist; tests manually descend nested blocks. Add names, paths, leaf iteration, and recursive filter/plot behavior.</td></tr><tr><td style="text-align:right;">EnSight/CGNS temporal reader interface</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">◐</td><td style="text-align:center;">✅</td><td style="text-align:right;"><code>timesteps</code>, <code>read_timestep</code>, <code>read_at</code>, and <code>eachstep</code>. <code>eachstep</code> lacks direct tests; borrowed snapshots and mutable timestep metadata need safer semantics.</td></tr><tr><td style="text-align:right;">General temporal readers/writers and temporal filters</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Generalize beyond EnSight/CGNS to XML/PVD/file series and reusable temporal pipelines.</td></tr><tr><td style="text-align:right;">Partitioned datasets, DataAssembly, and AMR collections</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Later modern-composite data-model work.</td></tr></tbody></table><h2 id="Plotting,-interoperability,-and-execution" tabindex="-1">Plotting, interoperability, and execution <a class="header-anchor" href="#Plotting,-interoperability,-and-execution" aria-label="Permalink to &quot;Plotting, interoperability, and execution {#Plotting,-interoperability,-and-execution}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">Raw binding</th><th style="text-align:center;">High-level API</th><th style="text-align:center;">Tested</th><th style="text-align:center;">Documented</th><th style="text-align:right;">Current scope / next gap</th></tr></thead><tbody><tr><td style="text-align:right;">Native Julia plotting with Makie</td><td style="text-align:center;">N/A</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Preferred plotting direction. Start with GeometryBasics conversion and optional Makie recipes; add static/interactive backends and off-screen tests.</td></tr><tr><td style="text-align:right;">Native VTK rendering bindings</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">No renderer/window/actor/mapper/camera classes are wrapped. Deferred while Makie is the preferred path; reconsider only for capabilities Makie cannot provide.</td></tr><tr><td style="text-align:right;">GeometryBasics conversion</td><td style="text-align:center;">N/A</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Practical first interoperability target for Makie: points, lines, faces, and field arrays. Define copy/ownership and mixed-cell/tessellation rules.</td></tr><tr><td style="text-align:right;">Meshes.jl conversion</td><td style="text-align:center;">N/A</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Complementary to GeometryBasics, not a strict Makie prerequisite. Requires a target representation for mixed-cell grids.</td></tr><tr><td style="text-align:right;">Tables.jl and tabular results</td><td style="text-align:center;">N/A</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">Field/probe arrays can get a Tables.jl adapter early; native VTK table round trips also require <code>vtkTable</code> wrapping.</td></tr><tr><td style="text-align:right;">ReadVTK/WriteVTK interoperability</td><td style="text-align:center;">N/A</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:right;">VTKBase cells and coordinate arrays support direct WriteVTK use; independent file oracles run in both directions where formats permit.</td></tr><tr><td style="text-align:right;">Scoped, severity-aware diagnostics</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:center;">◐</td><td style="text-align:right;">A process-global output buffer exists and <code>update!</code> throws on any text. Scoped collection, warning/error separation, and concurrent-pipeline tests are Stage 0 work.</td></tr><tr><td style="text-align:right;">MPI-aware distributed pipelines</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">◐</td><td style="text-align:right;">MPI libraries are preloaded for <code>VTK_jll</code>, but controllers, rank-aware pipelines, ghost exchange, and multi-rank tests are not exposed.</td></tr></tbody></table>',16)])])}const h=e(d,[["render",i]]);export{x as __pageData,h as default};
